"""stages.verify.soc: generated by the graph.py split (P1)."""

from __future__ import annotations


from ...flow import gates as gates_mod, ladder, outcome
from ...runtime import effects, commands as commands_mod, stage_services
from ...runtime.tools import SOC_WORKSPACE_SUBDIR
from ...stages.implement import intrinsics
from ...state import CfuDesignState


def generate_soc(state: CfuDesignState) -> CfuDesignState:
    """Rung 2: generate the SoC from the overlaid agent design.

    This is the hardware gate: Scala compilation, SpinalHDL elaboration and
    Verilog generation all happen here, so a broken design stops the run before
    any software is written.
    """
    rung = "hw_build"
    reason = stage_services._profile_reason(state)
    if reason:
        result = stage_services._skipped_result("sbt MiCoSocGen (agent overlay)", state, reason)
        result["rung"] = rung
        stage_services._write_ladder_artifact(state, rung, [result], "planned", reason)
        return {
            "validation_results": [result],
            "stage_jobs": "validation",
            **outcome.stage_result(state, rung=rung, ok=False, skipped=True, reason=reason,
                                   history=f"Skipped SoC generation ({reason})."),
        }

    toolbox = stage_services._toolbox_for_stage(state, "validation")
    isa_spec = state.get("isa_spec", {}) or {}
    commands = commands_mod.agent_cfu_overlay_commands(state, isa_spec) or commands_mod._legacy_ladder_commands(state, toolbox)["generate"]
    results: list[dict] = []
    impl_gate = gates_mod._rung_gate(state, "implementation_hw")
    if impl_gate and not impl_gate.get("ok", False):
        # The hardware rung produced no applied design, so the workspace still
        # holds the seeded scaffold. Compiling that would "pass" while validating
        # nothing, so fail the rung here and let the ladder repair the implementation.
        errors: list[str] = [
            "the hardware rung did not apply a design change; "
            "refusing to generate the SoC from the scaffold "
            "(the implementation_hw answer must contain an "
            "EDIT_BEGIN/FILE_BEGIN/PATCH_BEGIN deliverable)"
        ]
    elif impl_gate.get("candidate_hash") and impl_gate.get("candidate_hash") != intrinsics._hardware_candidate_hash(state, toolbox):
        errors = [
            "hardware candidate changed after implementation; refusing to validate stale implementation evidence"
        ]
    else:
        errors = commands_mod._missing_design_files(state)
        if errors:
            errors = [f"hardware design file is missing or empty: {', '.join(errors)}"]
        elif not commands:
            errors.append("no SoC generation command is available for this run")
        else:
            for command in commands:
                result = effects.run_command(
                    state,
                    toolbox,
                    command,
                stage="validation",
                    rung=rung)
                results.append(result)
                if result.get("returncode") not in (0, None):
                    errors.append(f"SoC generation failed: {' '.join(command)[:200]}")
                    break

    rtl = commands_mod._soc_rtl_path(state)
    if not errors and rtl is not None and not rtl.is_file():
        errors.append(f"SoC generation produced no RTL at {state.get('run_root')}/{SOC_WORKSPACE_SUBDIR}/MiCoSoc.v")

    ok = not errors and bool(results) and all(r.get("returncode") == 0 for r in results)
    stage_services._write_ladder_artifact(state, rung, results, "passed" if ok else "failed", "")

    retry = ladder._delivery_retry_transition(
        state, rung, "implement", ok,
        rejection=bool(impl_gate) and not impl_gate.get("ok", False),
    )
    if retry is not None:
        extra, next_node = retry
    else:
        extra, next_node = ladder._ladder_transition(
            state,
            rung,
            ok=ok,
            # The conformance micro-test runs before any software decision is final.
            default="check_conformance",
            repair_target="implement",
        )
    gates = {
        **state.get("gates", {}),
        rung: {
            "ok": ok,
            "skipped": False,
            "commands": len(results),
            "next": next_node,
        },
    }
    # iteration_history is append-annotated: these are only this node's new lines.
    history = ["Generated the SoC from the agent design."]
    extra["iteration_history"] = [*(extra.get("iteration_history") or []), *history]
    update = {
        "validation_results": results,
        "stage_jobs": "validation",
        "errors": errors,
        "gates": gates,
    }
    return ladder._apply_transition(update, extra)
